"""AgroVista compact dashboard. Run: streamlit run app/agrovista_dashboard92.py
The dashboard reads the menu catalogue written by 05_Menu_Catalogue_DuckDB.
Put in AgroVista_V2/app/, keeping the existing assets/foods directory in the
project root. The old app is not overwritten. Uses today's Kuala Lumpur date.
Dependencies: python -m pip install "streamlit==1.67.0" duckdb pandas numpy plotly tzdata
Optional item photos: assets/foods/<item_code>.webp|png|jpg|jpeg.
Without a local item photo an offline product illustration is displayed.
The state highlight map and its MIT licence are embedded; no map downloads.
Buying guidance is disabled on stale/incomplete forecast windows. The minimum
saving percentage is a user preference, not a confidence interval.
Validated using synthetic DuckDB data and Streamlit AppTest, not the user's DB.
"""
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import os, sys, json, html, base64, zlib
from hashlib import blake2s
import numpy as np
import pandas as pd
import duckdb
import plotly.graph_objects as go
from plotly.colors import sample_colorscale
import streamlit as st

GREEN='#0f7b5a'; INK='#12332a'; BLUE='#3b82c4'; RED='#c0463f'; MUTED='#5d7268'; AMBER='#c98a2e'
FONT='Inter, "Segoe UI", system-ui, -apple-system, Arial, sans-serif'
FORECAST='agrovista_v2_forecast_current'
# MIT state boundaries from atifmustaffa/malaysia-geojson, bundled offline below.
