def recipe_menu_rows():
    return [(menu_order,name,item_order,code,grams/1000,'1kg')
            for menu_order,(name,recipe) in enumerate(RECIPE_MENUS.items(),1)
            for item_order,(code,grams) in enumerate(recipe['grams'],1)]


def seed_basket_menus(db):
    rows=recipe_menu_rows()
    with duckdb.connect(str(db)) as con:
        con.begin()
        con.execute("""CREATE TABLE IF NOT EXISTS agrovista_basket_menu_ingredients (
            menu_order INTEGER NOT NULL, menu_name VARCHAR NOT NULL,
            ingredient_order INTEGER NOT NULL, item_code INTEGER NOT NULL,
            quantity DECIMAL(8,2) NOT NULL CHECK (quantity > 0),
            expected_unit VARCHAR NOT NULL, PRIMARY KEY (menu_name,item_code)
        )""")
        con.executemany("""INSERT INTO agrovista_basket_menu_ingredients
            VALUES (?,?,?,?,?,?) ON CONFLICT (menu_name,item_code) DO NOTHING""",rows)
        con.commit()
    print(f'Menu templates seeded in {db}')


def project_root(db):
    return db.parent.parent.parent if db.parent.name=='database' and db.parent.parent.name=='data' else db.parent

def signature(db):
    s=db.stat();wal=Path(str(db)+'.wal');return (s.st_mtime_ns,s.st_size,wal.stat().st_mtime_ns if wal.exists() else 0)

@st.cache_data(ttl=300,max_entries=8,show_spinner=False)
def sql(db,stamp,query,params=()):
    from cloud_runtime import query_dataframe
    return query_dataframe(db,query,params)

class Store:
    def __init__(self,db):
        self.db=str(db);self.stamp=signature(db)
        self.tables=set(self.q('SHOW TABLES')['name'])
        self.cols={t:set(self.q(f'DESCRIBE {ident(t)}')['column_name']) for t in ['lookup_items','lookup_premises','clean_joined_prices',FORECAST,'daily_state_prices'] if t in self.tables}
        if 'clean_joined_prices' not in self.tables:
            raise RuntimeError('Missing clean_joined_prices from Notebook 02. Historical and premise analysis need this table.')
        needed={'date','state','item_code','premise_code','price'}
        missing=needed-self.cols['clean_joined_prices']
        if missing:raise RuntimeError('Historical table is missing columns: '+', '.join(sorted(missing)))
        self.source=self.make_source()
    def q(self,query,params=()):return sql(self.db,self.stamp,query,tuple(params))
    def make_source(self):
        # Single normalized SQL projection. No full history is read into Python.
        cc=self.cols['clean_joined_prices'];joins=[];fields=['c.date','c.state','c.item_code','c.premise_code','c.price']
        for table,alias,key in [('lookup_items','i','item_code'),('lookup_premises','p','premise_code')]:
            if table in self.tables and key in self.cols[table]:
                joins.append(f'LEFT JOIN (SELECT * EXCLUDE(rn) FROM (SELECT *, ROW_NUMBER() OVER(PARTITION BY {key}) rn FROM {table}) WHERE rn=1) {alias} ON c.{key}={alias}.{key}')
        for name,alias,table,fallback in [('item','i','lookup_items',"'Item ' || CAST(c.item_code AS VARCHAR)"),('unit','i','lookup_items',"''"),('item_category','i','lookup_items',"'Uncategorised'"),('premise','p','lookup_premises',"'Premise ' || CAST(c.premise_code AS VARCHAR)"),('district','p','lookup_premises',"'Unknown district'"),('premise_type','p','lookup_premises',"'Unknown type'"),('address','p','lookup_premises',"''")]:
            candidates=[]
            if name in cc:candidates.append(f'NULLIF(CAST(c.{ident(name)} AS VARCHAR),\'\')')
            if table in self.tables and name in self.cols[table] and ('item_code' if alias=='i' else 'premise_code') in self.cols[table]:candidates.append(f'NULLIF(CAST({alias}.{ident(name)} AS VARCHAR),\'\')')
            fields.append('COALESCE('+','.join(candidates+[fallback])+f') AS {ident(name)}' if candidates else fallback+f' AS {ident(name)}')
        return '(SELECT '+','.join(fields)+' FROM clean_joined_prices c '+' '.join(joins)+')'
    def snapshot(self):
        d=self.q('SELECT MAX(CAST(date AS DATE)) last_date FROM clean_joined_prices')
        if pd.notna(d.iloc[0,0]):return pd.Timestamp(d.iloc[0,0])
        if 'daily_state_prices' in self.tables and 'date' in self.cols['daily_state_prices']:
            d=self.q('SELECT MAX(CAST(date AS DATE)) last_date FROM daily_state_prices')
            if pd.notna(d.iloc[0,0]):return pd.Timestamp(d.iloc[0,0])
        return None
    def eligible(self):
        if hasattr(self,'_eligible'):return self._eligible
        batch=self.batch()
        if batch is None:
            self._eligible=pd.DataFrame(columns=['level','state','item_code','premise_code'])
        else:
            self._eligible=self.q(f"""SELECT level,state,item_code,premise_code
            FROM {FORECAST} WHERE batch_id=? AND level IN ('state','premise')
            AND state IS NOT NULL AND item_code IS NOT NULL
            AND (level='state' OR premise_code IS NOT NULL)
            GROUP BY level,state,item_code,premise_code,forecast_today
            HAVING COUNT(*)=7 AND COUNT(DISTINCT CAST(forecast_date AS DATE))=7
            AND COUNT(*) FILTER(WHERE predicted_price>0 AND isfinite(predicted_price))=7
            AND MIN(CAST(forecast_date AS DATE)-CAST(forecast_today AS DATE))=0
            AND MAX(CAST(forecast_date AS DATE)-CAST(forecast_today AS DATE))=6""",[str(batch.batch_id)])
        return self._eligible
    def catalogue(self,root):
        codes=set(int(x) for x in self.eligible().item_code)
        if not codes:return pd.DataFrame(columns=['item_code','item','unit','item_category','label'])
        if 'lookup_items' in self.tables and {'item_code','item'}<=self.cols['lookup_items']:
            fields=[ident(c) if c in self.cols['lookup_items'] else f"'' AS {ident(c)}" for c in ['item_code','item','unit','item_category']]
            d=self.q('SELECT '+','.join(fields)+' FROM lookup_items').drop_duplicates('item_code')
        else:
            d=self.q(f'SELECT DISTINCT item_code,item,unit,item_category FROM {self.source}')
        if codes:
            d=d[d.item_code.isin(codes)].copy();known=set(d.item_code)
            missing=[{'item_code':c,'item':f'Item {c}','unit':'','item_category':'Uncategorised'} for c in codes-known]
            if missing:d=pd.concat([d,pd.DataFrame(missing)],ignore_index=True)
        d=d.dropna(subset=['item_code']);d.item_code=d.item_code.astype(int)
        for col in ['item','unit','item_category']:d[col]=d[col].fillna('').astype(str)
        d['label']=d['item']+' · '+d.unit+' ['+d.item_code.astype(str)+']'
        return d.sort_values(['item','item_code']).reset_index(drop=True)
    def premises(self):
        if 'lookup_premises' in self.tables and {'premise_code','state'}<=self.cols['lookup_premises']:
            fields=[ident(c) if c in self.cols['lookup_premises'] else f"'' AS {ident(c)}" for c in ['premise_code','premise','state','district','premise_type','address']]
            d=self.q('SELECT '+','.join(fields)+' FROM lookup_premises').drop_duplicates('premise_code')
        else:d=self.q(f'SELECT DISTINCT premise_code,premise,state,district,premise_type,address FROM {self.source}')
        eligible=self.eligible()
        served=eligible[eligible.level.eq('premise')][['state','premise_code']].drop_duplicates()
        # The forecast catalogue owns eligibility; lookup provides names only.
        d=served.merge(d,on=['state','premise_code'],how='left')
        d=d.dropna(subset=['premise_code','state']);d.premise_code=d.premise_code.astype(int)
        for col in ['premise','district','premise_type','address']:d[col]=d[col].fillna('Unknown' if col!='address' else '').astype(str)
        d['label']=d.premise+' ['+d.premise_code.astype(str)+']'
        return d.sort_values('label')
    def history(self,state,item,start,end,premise=None):
        where='state=? AND item_code=? AND date BETWEEN CAST(? AS DATE) AND CAST(? AS DATE)'
        params=[state,int(item),str(pd.Timestamp(start).date()),str(pd.Timestamp(end).date())]
        if premise is not None:where+=' AND premise_code=?';params.append(int(premise))
        raw=self.q(f'''WITH premise_daily AS (
            SELECT CAST(date AS DATE) date,premise_code,MEDIAN(price) price
            FROM clean_joined_prices WHERE {where} AND price>0 AND isfinite(price)
            GROUP BY CAST(date AS DATE),premise_code
        )
        SELECT date,MEDIAN(price) price,COUNT(DISTINCT premise_code) reporters
        FROM premise_daily GROUP BY date ORDER BY date''',params)
        frames=[]
        if premise is None and 'daily_state_prices' in self.tables:
            cols=self.cols['daily_state_prices']
            value=next((c for c in ['median_price','price'] if c in cols),None)
            if value and {'date','state','item_code'}<=cols:
                cached=self.q(f"""SELECT CAST(date AS DATE) date,MEDIAN({ident(value)}) price,
                NULL::BIGINT reporters FROM daily_state_prices
                WHERE state=? AND item_code=? AND date BETWEEN CAST(? AS DATE) AND CAST(? AS DATE)
                AND {ident(value)}>0 AND isfinite({ident(value)})
                GROUP BY CAST(date AS DATE) ORDER BY date""",[state,int(item),str(pd.Timestamp(start).date()),str(pd.Timestamp(end).date())])
                if not cached.empty:frames.append(cached.assign(history_source='daily_state_prices'))
        if not raw.empty:frames.append(raw.assign(history_source='clean_joined_prices'))
        if not frames:return pd.DataFrame(columns=['date','price','reporters','history_source'])
        # Refreshed raw history takes precedence on overlapping dates; older state
        # aggregates fill genuine missing dates only, without averaging sources.
        result=pd.concat(frames,ignore_index=True).drop_duplicates('date',keep='last')
        return result.sort_values('date').reset_index(drop=True)
    def observed(self,codes,start,end,state=None,district=None,premise=None,served_only=True):
        where=['item_code IN (SELECT UNNEST(?::BIGINT[]))','date BETWEEN CAST(? AS DATE) AND CAST(? AS DATE)','price>0','isfinite(price)']
        params=[list(map(int,codes)),str(pd.Timestamp(start).date()),str(pd.Timestamp(end).date())]
        for col,val in [('state',state),('district',district),('premise_code',premise)]:
            if val is not None:where.append(f'{col}=?');params.append(int(val) if col=='premise_code' else val)
        if served_only:
            batch=self.batch()
            if batch is None:return pd.DataFrame(columns=['date','state','item_code','premise_code','item','unit','item_category','premise','district','premise_type','price'])
            where.append(f'''(state,item_code,premise_code) IN (
                SELECT state,item_code,premise_code FROM {FORECAST}
                WHERE batch_id=? AND level='premise' AND premise_code IS NOT NULL
                GROUP BY state,item_code,premise_code,forecast_today
                HAVING COUNT(*)=7 AND COUNT(DISTINCT CAST(forecast_date AS DATE))=7
                AND COUNT(*) FILTER(WHERE predicted_price>0 AND isfinite(predicted_price))=7
                AND MIN(CAST(forecast_date AS DATE)-CAST(forecast_today AS DATE))=0
                AND MAX(CAST(forecast_date AS DATE)-CAST(forecast_today AS DATE))=6)''')
            params.append(str(batch.batch_id))
        # Return daily premise medians, not individual raw observations.
        return self.q(f'''SELECT CAST(date AS DATE) date,state,item_code,premise_code,
        ANY_VALUE(item) item,ANY_VALUE(unit) unit,ANY_VALUE(item_category) item_category,
        ANY_VALUE(premise) premise,ANY_VALUE(district) district,ANY_VALUE(premise_type) premise_type,
        MEDIAN(price) price FROM {self.source} WHERE {' AND '.join(where)}
        GROUP BY CAST(date AS DATE),state,item_code,premise_code''',params)
    def batch(self):
        req={'batch_id','forecast_today','forecast_date','level','state','item_code','premise_code','predicted_price'}
        if FORECAST not in self.tables or not req<=self.cols[FORECAST]:return None
        sort='MAX(generated_at_utc)' if 'generated_at_utc' in self.cols[FORECAST] else 'MAX(forecast_today)'
        d=self.q(f'SELECT batch_id,MAX(forecast_today) forecast_today,{sort} AS generated_time FROM {FORECAST} GROUP BY batch_id ORDER BY generated_time DESC,batch_id DESC LIMIT 1')
        return d.iloc[0] if len(d) else None
    def forecasts(self,batch,level,state=None,codes=None,premise=None):
        if batch is None:return pd.DataFrame()
        where=['batch_id=?','level=?'];p=[str(batch.batch_id),level]
        if state is not None:where.append('state=?');p.append(state)
        if codes is not None:where.append('item_code IN (SELECT UNNEST(?::BIGINT[]))');p.append(list(map(int,codes)))
        if premise is not None:where.append('premise_code=?');p.append(int(premise))
        fields=['forecast_today','forecast_date','level','state','item_code','premise_code','predicted_price']
        fields += [c for c in ['last_observed_date','prediction_kind'] if c in self.cols[FORECAST]]
        d=self.q('SELECT '+','.join(fields)+f' FROM {FORECAST} WHERE '+' AND '.join(where),p)
        if d.empty:return d
        d['forecast_date']=pd.to_datetime(d.forecast_date).dt.normalize()
        d['forecast_today']=pd.to_datetime(d.forecast_today).dt.normalize()
        return complete_forecasts(d)

def complete_forecasts(d):
    if d.empty:return d
    d=d.copy();d['predicted_price']=pd.to_numeric(d.predicted_price,errors='coerce')
    d=d[np.isfinite(d.predicted_price)&d.predicted_price.gt(0)]
    # Batch window is anchored to forecast_today, never shifted/relabelled on stale data.
    dates=(d.forecast_date-d.forecast_today).dt.days
    d=d[dates.between(0,6)]
    keys=['level','state','item_code','premise_code']
    g=d.groupby(keys,dropna=False)
    valid=g.forecast_date.transform('nunique').eq(7)&g.forecast_date.transform('size').eq(7)
    return d[valid].sort_values('forecast_date')

def recommendation(f,today):
    if f.empty:return {'status':'Unavailable','detail':'No complete seven-day forecast for this selection.'}
    f=f.sort_values('forecast_date')
    if list(f.forecast_date)!=list(pd.date_range(today,periods=7)):
        return {'status':'Unavailable','detail':'Refresh the saved forecast for today before using buying guidance.'}
    # Use the same cent precision as the price cards.
    cents=[int(f'{float(price):.2f}'.replace('.','')) for price in f.predicted_price]
    current=cents[0]
    lowest=min(cents)
    if lowest==max(cents):
        return {'status':'Stable','detail':'All seven forecast prices are the same to the nearest sen.'}
    best=f.forecast_date.iloc[cents.index(lowest)]
    if best==today:
        return dict(status='Lowest forecast today',detail='Today shares the minimum if prices are tied.',best=best)
    saving=current-lowest
    return dict(status='Lower forecast ahead',detail='Lowest forecast on '+datefmt(best),low=lowest/100,
                best=best,saving=saving/100,pct=saving/current*100 if current else 0)

