def choose(label,options,key,format_func=None,default=None,on_change=None,callback_args=(), search_context=None):
    options=list(options)
    if not options:st.info(f'No options available: {label}');st.stop()
    if key in st.session_state and st.session_state[key] not in options:del st.session_state[key]
    if key not in st.session_state and default in options:st.session_state[key]=default
    kwargs=dict(label=label,options=options,key=key)
    if format_func is not None:kwargs['format_func']=format_func
    if on_change is not None:kwargs.update(on_change=on_change,args=callback_args)
    if len(options) <= 8:
        return st.pills(**kwargs, selection_mode='single', required=True, default=None if key in st.session_state else options[0])

    format_option = format_func or str
    with st.container(border=True, key=f'choices_{key}'):
        search_key = f'search_{key}_{search_context}'
        query = st.text_input(f'Find {label.lower()}', key=search_key).strip().casefold()
        if query:
            st.button('Clear search', key=f'clear_{key}',
                      on_click=st.session_state.__setitem__, args=(search_key, ''))
        visible = [value for value in options if query in str(format_option(value)).casefold()]
        current = st.session_state.get(key, options[0])
        if current not in visible:
            visible.insert(0, current)
        if query and not any(query in str(format_option(value)).casefold() for value in visible):
            st.caption('No matching choices.')
        kwargs['options'] = visible
        with st.container(height=128, border=False):
            return st.radio(**kwargs)

