def restore_basket_widget(widget_key,saved_key,default,options=None):
    # Widget keys disappear when their controls are hidden or the page changes.
    # Durable keys are never bound to widgets and survive those transitions.
    if saved_key not in st.session_state:
        existing=st.session_state.get(widget_key,default)
        st.session_state[saved_key]=list(existing) if isinstance(existing,list) else existing
    value=st.session_state[saved_key]
    if isinstance(value,list):value=[v for v in value if options is None or v in options]
    elif options is not None and value not in options:value=default
    st.session_state[widget_key]=value


