def state_map(state,key,height=145,coverage=None):
    if coverage is None:
        overview_panel('State on map',state)
    if not MAP_DATA:st.info('State boundary map unavailable.');return
    geo=json.loads(zlib.decompress(base64.b64decode(MAP_DATA)))
    aliases={'pulau pinang':'penang','w.p. kuala lumpur':'kuala lumpur','w.p. putrajaya':'putrajaya','w.p. labuan':'labuan','melaka':'malacca'}
    def norm(s):
        s=str(s).lower().replace('wilayah persekutuan ','').strip();return aliases.get(s,s)
    selected = norm(state)
    counts = {} if coverage is None else {norm(name): int(count) for name,count in coverage.items()}
    maximum = max(counts.values(), default=0)
    colorscale = ['#e7f2e9', '#81b794', '#17624a']
    ramp = ','.join(colorscale)
    # Draw the selected boundary last so the neighbouring polygons cannot cover its outline.
    features = sorted(geo['features'], key=lambda feature: norm(feature['properties']['name']) == selected)
    fig = go.Figure()
    outlined = []
    for feature in features:
        name = feature['properties']['name']
        chosen = norm(name) == selected
        count = counts.get(norm(name), 0)
        if coverage is None:
            fill = GREEN if chosen else '#e1e8e1'
            hover = esc(name)
        else:
            fill = sample_colorscale(colorscale, [count / max(maximum, 1)])[0]
            hover = f'{esc(name)}<br>{count:,} forecast items'
        geom = feature['geometry']
        polygons = geom['coordinates'] if geom['type']=='MultiPolygon' else [geom['coordinates']]
        for polygon in polygons:
            x,y = zip(*[(pt[0],pt[1]) for pt in polygon[0]])
            fig.add_trace(go.Scatter(
                x=x,y=y,mode='lines',fill='toself',fillcolor=fill,hoveron='fills',
                line=dict(color='#fff',width=.65),
                name=name,hovertemplate=hover+'<extra></extra>',showlegend=False,
            ))
            if chosen and coverage is not None:
                outlined.append((x,y))
    for color,width in [('#fff',4.4),('#d99a16',2.6)]:
        for x,y in outlined:
            fig.add_trace(go.Scatter(x=x,y=y,mode='lines',line=dict(color=color,width=width),
                                     hoverinfo='skip',showlegend=False))
    fig.update_xaxes(visible=False,range=[99.4,119.7],fixedrange=True,constrain='domain')
    fig.update_yaxes(visible=False,range=[.7,7.5],scaleanchor='x',scaleratio=1,
                     fixedrange=True,constrain='domain')
    if coverage is None:
        chart(fig,key,height=height,toolbar=False,margin=dict(l=4,r=4,t=4,b=4))
        if not any(norm(feature['properties']['name']) == selected for feature in features):
            st.info('No matching boundary for this state name.')
    else:
        chart(fig,key,height=height,toolbar=False,margin=dict(l=4,r=4,t=6,b=6))
        if maximum:
            st.html(f'<div class="overview-map-legend">0<span class="overview-map-scale" '
                    f'style="background:linear-gradient(to right,{ramp})"></span>{maximum:,} items</div>')
        else:
            st.info('No complete state-level forecasts available.')


def daily_cards(f,today,rec):
    if f.empty:return
    cards=[]
    for _,row in f.sort_values('forecast_date').iterrows():
        day=pd.Timestamp(row.forecast_date);is_today=day==today
        best=day==rec.get('best')
        cls='day'+(' today' if is_today else '')+(' best' if best else '')
        tag='TODAY · LOWEST' if is_today and best else ('TODAY' if is_today else ('LOWEST' if best else day.strftime('%a')))
        cards.append(f'<div class="{cls}"><span class="tag">{tag}</span><div>{day:%d %b}</div><strong>{money(row.predicted_price)}</strong></div>')
    st.markdown('<div class="day-grid">'+''.join(cards)+'</div>',unsafe_allow_html=True)

