def forecast_baskets(forecasts,premises,quantities,target,states,districts):
    """Rank identical complete baskets only; missing item forecasts never cost zero."""
    cols=['state','premise_code','premise','district','address','reported_items','total','complete','rank']
    if forecasts.empty:return pd.DataFrame(columns=cols),pd.DataFrame()
    f=forecasts[forecasts.forecast_date.eq(pd.Timestamp(target)) & forecasts.state.isin(states) & forecasts.item_code.isin(quantities)].copy()
    f=f[np.isfinite(f.predicted_price)&f.predicted_price.gt(0)]
    if f.duplicated(['state','premise_code','item_code']).any():raise RuntimeError('Duplicate forecast item/premise rows: basket totals have not been calculated.')
    if f.empty:return pd.DataFrame(columns=cols),f
    metadata=premises[['state','premise_code','premise','district','address']].drop_duplicates(['state','premise_code'])
    f=f.merge(metadata,on=['state','premise_code'],how='left')
    f['district']=f.district.fillna('Unknown district');f['district_label']=f.state+' · '+f.district
    if districts:f=f[f.district_label.isin(districts)].copy()
    if f.empty:return pd.DataFrame(columns=cols),f
    f['quantity']=f.item_code.map(quantities);f['subtotal']=f.predicted_price*f.quantity
    g=f.groupby(['state','premise_code'],as_index=False).agg(premise=('premise','first'),district=('district','first'),address=('address','first'),reported_items=('item_code','nunique'),total=('subtotal','sum'))
    g['complete']=g.reported_items.eq(len(quantities)) & np.isfinite(g.total)
    g.loc[~g.complete,'total']=np.nan
    g['rank']=g.total.rank(method='min').astype('Int64')
    return g.sort_values(['total','state','premise'],na_position='last').reset_index(drop=True),f


def add_menu_ingredients(ingredients):
    basket=st.session_state.setdefault('comparison_basket',[])
    present={int(entry['item_code']) for entry in basket}
    quantities={}
    for code,quantity in ingredients:
        quantities[code]=quantities.get(code,0.0)+quantity
    for code,quantity in quantities.items():
        if code not in present:
            basket.append({'item_code':code,'quantity':round(quantity,3)})
            st.session_state.pop(f'basket_qty_{code}',None)


def basket_item_costs(lines, catalogue, best_code, focus_code, codes):
    comparing=best_code!=focus_code
    details=lines[lines.premise_code.eq(best_code)].set_index('item_code').reindex(codes)
    details=details.join(catalogue.set_index('item_code')[['item','unit']])
    if comparing:
        selected=lines[lines.premise_code.eq(focus_code)].set_index('item_code')
        details['selected_cost']=selected.subtotal
        details['cost_gap']=details.selected_cost-details.subtotal
    vertical=len(details)>5
    chart_height=238
    fig=go.Figure()
    tick_labels=[esc(name if len(name)<=23 else name[:21]+'…') for name in details.item]
    item_keys=[f'item-{code}' for code in codes]
    series=[('Cheapest premise','subtotal',GREEN)]
    if comparing:
        series.append(('Selected premise','selected_cost','#9d661c'))
    for label,field,color in series:
        hover=[f'<b>{esc(row.item)}</b><br>{row.quantity:g} × {esc(row.unit)}'
               + (f'<br>Selected vs cheapest: RM {row.cost_gap:+.2f}' if comparing else '')
               for row in details.itertuples()]
        amounts=details[field].tolist()
        fig.add_bar(x=item_keys if vertical else amounts,y=amounts if vertical else item_keys,
                    orientation='v' if vertical else 'h',name=label,marker_color=color,
                    text=[money(amount) for amount in amounts],textposition='outside',cliponaxis=False,
                    customdata=hover,hovertemplate='%{customdata}<br>'+label+' · %{text}<extra></extra>')
    maximum=max(details[field].max() for _,field,_ in series)
    amount_axis=dict(title='Item subtotal (RM)',range=[0,maximum*1.25],tickprefix='RM ')
    items_axis=dict(type='category',tickmode='array',tickvals=item_keys,ticktext=tick_labels,
                    categoryorder='array',categoryarray=item_keys,showgrid=False)
    fig.update_layout(barmode='group',bargap=.5 if len(details)==1 else .33,showlegend=comparing)
    if vertical:
        fig.update_xaxes(**items_axis,tickangle=-22)
        fig.update_yaxes(**amount_axis)
    else:
        fig.update_xaxes(**amount_axis)
        fig.update_yaxes(**items_axis)
        if len(details)==1:
            fig.update_yaxes(range=[1,-1])
        else:
            fig.update_yaxes(autorange='reversed')
    with st.container(key='basket_item_plot',gap=None):
        if vertical:
            width=len(details)*(148 if comparing else 108)+64
            st.html(f'<style>.st-key-basket_item_plot{{--basket-item-plot-width:{width}px}}</style>')
        chart(fig,'basket_item_costs',chart_height,toolbar=False,
              legend=dict(orientation='h',x=.5,xanchor='center',y=1.03,yanchor='bottom',font_size=11),
              margin=dict(l=8,r=18,t=28 if comparing else 10,b=18))


def basket_district_ranges(complete, state, focus_district):
    overview_panel('Basket price range by district',f'{state} · Lowest and highest complete basket totals')
    areas=complete.groupby('district',as_index=False).agg(lowest=('total','min'),highest=('total','max'))
    areas=areas.sort_values(['lowest','district'])
    floor,ceiling=areas.lowest.min(),areas.highest.max()
    span=ceiling-floor
    rows=[]
    for entry in areas.itertuples():
        current=' aria-current="true"' if entry.district==focus_district else ''
        start=(entry.lowest-floor)/span*90+5 if span else 50
        width=(entry.highest-entry.lowest)/span*90 if span else 0
        same=' data-single' if entry.lowest==entry.highest else ''
        prices=money(entry.lowest) if same else f'{money(entry.lowest)} – {money(entry.highest)}'
        rows.append(f'<li class="basket-district-row"{current}>'
                    f'<span class="prediction-rank-place" title="{esc(entry.district)}">{esc(entry.district)}</span>'
                    f'<span class="basket-district-track" aria-hidden="true"><i{same} style="left:{start:.3f}%;width:{width:.3f}%"></i></span>'
                    f'<span class="basket-district-prices">{prices}</span></li>')
    st.html(f'<ul class="basket-district-list" role="list" tabindex="0" aria-label="Basket price range by district" '
            f'data-scroll-target="{esc(focus_district or "")}">{"".join(rows)}</ul>')


def scroll_to_rankings(targets):
    if not targets:
        return
    target_json=json.dumps(targets).replace('<','\\u003c')
    source=f"""
            <script>
            const pending = new Map(Object.entries({target_json}));
            const page = window.parent.document;
            const reveal = () => {{
                for (const [selector, target] of pending) {{
                    const list = page.querySelector(selector);
                    if (list?.dataset.scrollTarget !== target) continue;
                    const row = list.querySelector('[aria-current="true"]');
                    if (!row) continue;
                    const bounds = list.getBoundingClientRect();
                    const selected = row.getBoundingClientRect();
                    if (selected.top < bounds.top || selected.bottom > bounds.bottom) {{
                        list.scrollTop += selected.top - bounds.top - (list.clientHeight - row.offsetHeight) / 2;
                    }}
                    pending.delete(selector);
                }}
                if (pending.size) return;
                observer.disconnect();
            }};
            const observer = new MutationObserver(reveal);
            observer.observe(page.body, {{childList: true, subtree: true, attributes: true,
                                         attributeFilter: ['data-scroll-target', 'aria-current']}});
            reveal();
            window.setTimeout(() => observer.disconnect(), 2000);
            </script>
        """
    with st.container(key='ranking_auto_scroll',gap=None):
        if hasattr(st,'iframe'):
            st.iframe(source,height=1,tab_index=-1)
        else:
            from streamlit.components.v1 import html as component_html
            component_html(source,height=0)


def price_comparison(store,cat,prem,root,today):
    page_header('Basket comparison','Compare the estimated cost of your full basket across shops.','Shopping')
    batch=store.batch()
    if not forecast_notice(batch,today):return
    eligible=store.eligible();eligible=eligible[eligible.level.eq('premise')]
    selectable=cat[cat.item_code.isin(eligible.item_code)]
    if selectable.empty:st.info('No complete premise forecasts available for basket comparison.');return
    states=sorted(eligible.state.unique().tolist())
    previous=st.session_state.get('_saved_basket_states',[])
    preferred=st.session_state.get('_basket_seed_state',previous[0] if previous else st.session_state.get('selected_state'))
    default_state=preferred if preferred in states else states[0]
    dates=list(pd.date_range(pd.Timestamp(batch.forecast_today),periods=7))

    target=today

    with st.container(border=True,key='basket_filters'):
        state_col,district_col,budget_col,item_col,menu_col=st.columns(
            [1,1.2,1.1,1,1],gap='small',vertical_alignment='bottom'
        )
        restore_basket_widget('basket_state','_saved_basket_state',default_state,states)
        state=state_col.selectbox('State',states,key='basket_state',on_change=remember_basket_widget,
                                  args=('basket_state','_saved_basket_state'))
        metadata=prem[prem.state.eq(state)]
        district_options=['All districts']+sorted(v for v in metadata.district.dropna().unique() if v and v!='All districts')
        saved_district=st.session_state.get('_saved_basket_district_by_state',{}).get(state,'All districts')
        st.session_state.basket_district=saved_district if saved_district in district_options else 'All districts'
        district=district_col.selectbox('District',district_options,key='basket_district',
                                       on_change=remember_basket_district,args=(state,))
        restore_basket_widget('basket_budget','_saved_basket_budget',None)
        budget=budget_col.number_input('Budget (RM) · optional',min_value=0.,max_value=100000000.,value=None,step=1.,
                                       format='%.2f',placeholder='Enter a budget',key='basket_budget',
                                       on_change=remember_basket_widget,args=('basket_budget','_saved_basket_budget'))
    chosen_states=[state]
    districts=[] if district=='All districts' else [state+' · '+district]
    area=f'{district}, {state}' if districts else state+' · All districts'
    area_premises=metadata if not districts else metadata[metadata.district.eq(district)]
    area_codes=eligible.loc[eligible.state.eq(state)&
        eligible.premise_code.isin(area_premises.premise_code),'item_code']
    available=selectable[selectable.item_code.isin(area_codes)]
    in_basket={int(entry['item_code']) for entry in st.session_state.get('comparison_basket',[])}

    @st.dialog('Menu catalog',width='large')
    def menu_catalog():
        fields=['menu_order','menu_name','ingredient_order','item_code','quantity','expected_unit']
        menus=pd.DataFrame(recipe_menu_rows(),columns=fields)
        recipe_metadata={}
        if {'menu_recipe_collection','menu_ingredient_mapping'} <= store.tables:
            menus=store.q("""SELECT r.menu_id,r.menu_name,r.ingredient_order,m.item_code,m.quantity,
                    m.expected_unit,r.source_url AS recipe_source,r.servings,r.original_measure,
                    r.ingredient_name,m.include_in_basket,m.mapping_status,m.mapping_reason
                FROM menu_recipe_collection AS r
                LEFT JOIN menu_ingredient_mapping AS m USING (menu_id,ingredient_order)
                ORDER BY r.menu_id,r.ingredient_order""")
        elif 'agrovista_menu_catalogue' in store.tables:
            menus=store.q("""SELECT menu_id,menu_name,ingredient_order,item_code,quantity,
                    expected_unit,recipe_source,servings,original_measure,ingredient_name,
                    include_in_basket,mapping_status
                FROM agrovista_menu_catalogue ORDER BY menu_id,ingredient_order""")
        elif 'agrovista_basket_menu_ingredients' in store.tables:
            saved=store.q("""SELECT menu_order,menu_name,ingredient_order,item_code,quantity,expected_unit
                FROM agrovista_basket_menu_ingredients ORDER BY menu_order,menu_name,ingredient_order""")
            replaced_names=set(MENU_IMAGE_CODES)|set(RECIPE_MENUS)
            custom=saved[~saved.menu_name.isin(replaced_names)]
            if not custom.empty:
                menus=pd.concat([menus,custom],ignore_index=True)
        if 'menu_id' in menus.columns:
            recipe_metadata=menus.drop_duplicates('menu_name').set_index('menu_name').to_dict('index')
        catalogue=cat.set_index('item_code')
        menu=st.session_state.get('catalog_menu_detail')
        if menu not in menus.menu_name.values:
            names=menus.menu_name.drop_duplicates().tolist()
            if not names:
                st.info('No menus are available in the catalogue.')
                return
            with st.container(key='catalog_menus_grid'):
                cards=st.columns(len(names),gap='small')
                for index,(card,name) in enumerate(zip(cards,names)):
                    details=recipe_metadata.get(name,RECIPE_MENUS.get(name,{}))
                    servings=details.get('servings')
                    with card,st.container(border=True):
                        image_code=details.get('menu_id') or menu_image_code(name)
                        src=asset_image(root,'menus',image_code)
                        photo=f'<img src="{src}" alt="" loading="lazy">' if src else '<span>No photo yet</span>'
                        st.html(f'<div class="menu-card-photo">{photo}</div>')
                        serving_text=f'{esc(servings)} servings' if pd.notna(servings) and servings else ''
                        st.html(f'<div class="menu-card-title">{esc(name)}</div>'
                                f'<div class="menu-card-meta">{serving_text}</div>')
                        st.button('View ingredients',key=f'catalog_menu_{index}',width='stretch',
                                  help=f'Select basket ingredients for {name}.',
                                  on_click=st.session_state.__setitem__,args=('catalog_menu_detail',name))
                        full_recipe_button(details.get('recipe_source',details.get('source')),name,
                                           f'catalog_recipe_{index}')
            return
        details=recipe_metadata.get(menu,RECIPE_MENUS.get(menu,{}))
        with st.container(key='menu_detail'):
            back_col,recipe_col=st.columns(2,gap='small')
            with back_col:
                st.button('Back to menus',icon=':material/arrow_back:',width='stretch',
                          on_click=st.session_state.pop,args=('catalog_menu_detail',None))
            with recipe_col:
                full_recipe_button(details.get('recipe_source',details.get('source')),menu,'menu_detail_recipe')
            servings=details.get('servings')
            meta=f'<p>{esc(servings)} servings · Ajinomoto Malaysia</p>' if pd.notna(servings) and servings else ''
            st.html(f'<div class="menu-detail-title"><h3>{esc(menu)}</h3>{meta}</div>')
            st.markdown('**Ingredients for basket comparison**')
        area_items=set(available.item_code)
        chosen=[]
        ingredients=menus[menus.menu_name.eq(menu)]
        if 'include_in_basket' in ingredients:
            costable=ingredients.include_in_basket.eq(1)
            other_ingredients=ingredients[~costable]
            ingredients=ingredients[costable]
        else:
            other_ingredients=ingredients.iloc[0:0]
        if ingredients.empty:
            st.info('This recipe has no ingredients with quantities ready for basket pricing.')
        with st.container(key='catalog_ingredients_grid'):
            cards=st.columns(max(1,len(ingredients)),gap='small')
            for card,entry in zip(cards,ingredients.itertuples()):
                code=int(entry.item_code)
                unit=str(catalogue.at[code,'unit']) if code in catalogue.index else ''
                name=str(catalogue.at[code,'item']) if code in catalogue.index else getattr(entry,'ingredient_name',f'Item {code}')
                valid=code in area_items and unit.lower().replace(' ','')==entry.expected_unit.lower().replace(' ','')
                status=' · In basket' if code in in_basket else ' · Unavailable' if not valid else ''
                can_add=valid and code not in in_basket
                with card,st.container(border=True):
                    catalog_image(root,pd.Series({'item':name,'item_code':code}))
                    st.markdown(f'<div class="catalog-name" title="{esc(name)}">{esc(name)}</div>',unsafe_allow_html=True)
                    measure=getattr(entry,'original_measure',None) or f'{float(entry.quantity):g} × {unit or entry.expected_unit}'
                    reason=getattr(entry,'mapping_reason','') or ''
                    basket_measure=f'{float(entry.quantity):g} × {entry.expected_unit}'
                    if reason.startswith('Estimated weight:'):
                        basket_measure=f'Estimated {float(entry.quantity)*1000:.0f} g'
                    st.html(f'<div class="menu-card-meta">{esc(measure)}<br>{esc(basket_measure)}</div>')
                    label=status.removeprefix(' · ') or 'Include'
                    if st.checkbox(label,value=can_add,disabled=not can_add,
                                   key=f'menu_pick_{menu}_{entry.ingredient_order}') and can_add:
                        chosen.append((code,float(entry.quantity)))
        if st.button('Add selected ingredients',key='catalog_menu_add',type='primary',disabled=not chosen):
            add_menu_ingredients(chosen)
            st.rerun()
        if not other_ingredients.empty:
            st.markdown('**Other recipe ingredients**')
            reasons={
                'unit_mismatch':'Needs a quantity in the pricing unit',
                'not_priced':'No basket price',
                'outside_scope':'Outside the price catalogue',
                'unresolved_variant':'Needs a matching product',
            }
            rows=[]
            for entry in other_ingredients.itertuples():
                reason=reasons.get(entry.mapping_status,'No basket price')
                rows.append(f'<li><strong>{esc(entry.ingredient_name)}</strong> · {esc(entry.original_measure)}'
                            f'<span>{esc(reason)}</span></li>')
            st.html('<ul class="menu-other-ingredients">'+''.join(rows)+'</ul>')

    # Items remain in the basket when a selected area lacks a forecast for them.
    known=set(selectable.item_code)
    basket=[entry for entry in st.session_state.get('comparison_basket',[]) if int(entry['item_code']) in known]
    st.session_state.comparison_basket=basket
    with item_col,st.container(key='basket_item_filter',gap=None):
        st.html('<div class="prediction-field-label">Food item</div>')
        if st.button('Browse item',icon=':material/shopping_basket:',width='stretch',type='primary',key='browse_basket_item'):
            item_catalog(root,available,in_basket)
    with menu_col,st.container(key='basket_menu_filter',gap=None):
        st.html('<div class="prediction-field-label">Menu</div>')
        if st.button('Browse menu',icon=':material/restaurant_menu:',width='stretch',type='primary',key='browse_basket_menu'):
            st.session_state.pop('catalog_menu_detail',None)
            menu_catalog()
    with st.container(border=True,key='basket_editor_panel'):
        item_count=f'{len(basket)} {"item" if len(basket)==1 else "items"}'
        overview_panel('Your basket',item_count if basket else 'Add individual items or start with a menu.')
        if not basket:
            st.html('<div class="basket-empty">Your basket is empty. Add items to compare their total across premises.</div>')
            return
        st.html('<div class="basket-table-head"><span>Item</span><span>Quantity</span><span>Action</span></div>')
        item_map=selectable.set_index('item_code')
        for entry in basket:
            item_code=int(entry['item_code'])
            item=item_map.loc[item_code].astype(object)
            item['item_code']=item_code
            image, caption=food_image(root,item)
            with st.container(key=f'basket_row_{item_code}'):
                name,qty,remove=st.columns([3,1,1],vertical_alignment='center',gap='small')
                with name:
                    st.html(f'<div class="basket-item-cell"><img class="basket-thumb" src="{image}" alt="" title="{esc(caption)}">'
                            f'<div><div class="basket-item-name">{esc(item["item"])}</div>'
                            f'<div class="basket-item-meta">{esc(item.unit)} per unit · {esc(item.item_category)}</div></div></div>')
                with qty:
                    entry['quantity']=st.number_input('Quantity for '+item['item']+' · '+item.unit,min_value=.001,
                        max_value=100000.,value=float(entry['quantity']),step=.001,format='%.3f',key=f'basket_qty_{item_code}',
                        label_visibility='collapsed',on_change=remember_basket_quantity,args=(item_code,))
                with remove:
                    st.button('Remove',key=f'basket_remove_{item_code}',on_click=remove_comparison_item,args=(item_code,),
                              help=f'Remove {item["item"]}')
    quantities={int(entry['item_code']):float(entry['quantity']) for entry in basket}
    codes=list(quantities)
    with st.spinner('Comparing saved forecast basket costs…'):
        forecasts=store.forecasts(batch,'premise',state,codes)
        ranked,lines=forecast_baskets(forecasts,prem,quantities,target,chosen_states,districts)
    complete=ranked[ranked.complete].copy()
    incomplete=ranked[~ranked.complete].copy()
    with st.container(border=True,key='basket_summary_panel'):
        overview_panel('Basket cost summary',f'{area} · {datefmt(target)} · {item_count}')
        if complete.empty:
            available_counts=lines.groupby('item_code').premise_code.nunique() if not lines.empty else pd.Series(dtype=int)
            missing=[item_map.loc[code,'item'] for code in codes if available_counts.get(code,0)==0]
            st.warning('No premise can price every item in this basket. Try All districts or adjust your basket.')
            if missing:
                st.caption('Items without forecasts in this area: '+', '.join(missing)+'.')
            elif not incomplete.empty:
                st.caption(f'{len(incomplete)} premises have forecasts for only part of the basket.')
            return
        best=complete.iloc[0]
        highest=complete.iloc[-1]
        spread=highest.total-best.total
        metrics=[
            ('Lowest basket total',money(best.total),best.premise+' · '+best.district),
            ('Highest basket total',money(highest.total),highest.premise+' · '+highest.district),
            ('Median basket total',money(complete.total.median()),'Across complete baskets'),
            ('Complete premises',f'{len(complete):,}',f'Full coverage for {item_count}'),
            ('Price spread',money(spread),'Highest minus lowest'),
        ]
        cards=''.join(f'<div class="basket-kpi{variant}">'
                      f'<span>{esc(label)}</span><strong>{esc(value)}</strong><small>{esc(detail)}</small></div>'
                      for (label,value,detail),variant in zip(metrics,(' primary',' high','','','')))
        st.html(f'<div class="basket-kpis">{cards}</div>')
        if budget is not None:
            budget_sen=int(round(budget*100))
            complete['within_budget']=complete.total.map(lambda value: int(round(float(f'{value:.2f}')*100))<=budget_sen)
            remaining=(budget_sen-int(round(float(f'{best.total:.2f}')*100)))/100
            status='Budget remaining' if remaining>=0 else 'Over budget'
            variant='' if remaining>=0 else ' over'
            st.html(f'<div class="basket-budget-line{variant}"><strong>{status} · {money(abs(remaining))}</strong>'
                    f' at the cheapest premise · {int(complete.within_budget.sum()):,} of {len(complete):,} within {money(budget)}</div>')

    complete['shop_label']=complete.premise+' · '+complete.district+' ['+complete.premise_code.astype(int).astype(str)+']'
    shop_labels=complete.set_index('premise_code').shop_label.to_dict()
    reference_options=['cheapest',*complete.premise_code.astype(int)]
    best_code=int(best.premise_code)
    with st.container(key='basket_comparison_row'):
        left,right=st.columns([1,1.15],gap='small')
    with left,st.container(border=True,key='comparison_ranking_panel'):
        overview_panel('Premise ranking','Lowest to highest · Scroll to see all complete baskets')
        restore_basket_widget('compare_reference','_saved_basket_reference','cheapest',reference_options)
        ref=st.selectbox('Compare with a premise',reference_options,key='compare_reference',
                         format_func=lambda value:'Cheapest premise' if value=='cheapest' else shop_labels[value],
                         on_change=remember_basket_widget,args=('compare_reference','_saved_basket_reference'))
        focus_code=best_code if ref=='cheapest' else int(ref)
        selected=complete[complete.premise_code.eq(focus_code)].iloc[0]
        comparing=focus_code!=best_code
        peak=complete.total.max()
        rows=[]
        for entry in complete.to_dict('records'):
            current=' aria-current="true"' if int(entry['premise_code'])==focus_code else ''
            place=entry['premise']+' · '+entry['district']
            within=' · Within budget' if entry.get('within_budget') else ''
            rows.append(f'<li{current}><span>#{int(entry["rank"])}</span>'
                        f'<span class="prediction-rank-place" title="{esc(place+within)}">{esc(place)}</span>'
                        f'<span class="prediction-rank-track" aria-hidden="true"><i style="width:{100*entry["total"]/peak:.2f}%"></i></span>'
                        f'<span class="prediction-rank-value">{money(entry["total"])}{" ✓" if within else ""}</span></li>')
        st.html(f'<ul class="prediction-rank-list" role="list" tabindex="0" aria-label="Premise basket ranking" data-scroll-target="{focus_code}">{"".join(rows)}</ul>')
    cheapest_trend=[]
    selected_trend=[]
    for day in dates:
        day_rank,_=forecast_baskets(forecasts,prem,quantities,day,chosen_states,districts)
        totals=day_rank.loc[day_rank.complete].set_index('premise_code').total
        cheapest_trend.append(float(totals.get(best_code,np.nan)))
        selected_trend.append(float(totals.get(focus_code,np.nan)))
    best_day=dates[int(np.nanargmin(selected_trend))]
    with right:
        gap=''
        if ref!='cheapest':
            difference=selected.total-best.total
            sign='+' if round(difference,2)>0 else ''
            gap=f'<span class="basket-price-gap">{sign}{money(difference)} vs cheapest premise</span>'
        st.html(f'<div class="prediction-rank-summary basket-premise-summary">'
                f'<div><div class="eyebrow">{"Your selected premise vs cheapest premise" if ref!="cheapest" else "Cheapest premise"}</div>'
                f'<div class="prediction-rank-name" title="{esc(selected.premise)}">{esc(selected.premise)}</div></div>'
                f'<div class="prediction-rank-number">#{int(selected["rank"]):,}<small> / {len(complete):,}</small></div>'
                f'<div class="prediction-rank-price"><strong>{money(selected.total)}</strong><span>today</span>{gap}</div></div>')
        with st.container(border=True,key='basket_trend_panel'):
            st.html('<h2 class="basket-forecast-title">7-day basket forecast</h2>')
            daily_cards(pd.DataFrame({'forecast_date':dates,'predicted_price':selected_trend}),today,{'best':best_day})
            fig=go.Figure(go.Scatter(x=dates,y=cheapest_trend,mode='lines+markers',connectgaps=False,
                                     name='Cheapest premise',line=dict(color=GREEN,width=2),
                                     hovertemplate=esc(best.premise)+'<br>RM %{y:.2f}'))
            if comparing:
                gaps=[f'<br>Difference: RM {value-base:+.2f}' if np.isfinite(value) and np.isfinite(base) else ''
                      for value,base in zip(selected_trend,cheapest_trend)]
                fig.add_trace(go.Scatter(x=dates,y=selected_trend,mode='lines+markers',connectgaps=False,
                                         name='Selected premise',line=dict(color='#9d661c',width=2,dash='dash'),
                                         marker=dict(symbol='diamond'),customdata=gaps,
                                         hovertemplate=esc(selected.premise)+'<br>RM %{y:.2f}%{customdata}'))
            fig.update_xaxes(tickformat='%d %b',tickvals=dates)
            fig.update_yaxes(title='Basket total (RM)')
            chart(fig,'basket_seven_day',230,toolbar=False,hovermode='x unified',
                  legend=dict(orientation='h',y=1.13,x=0,font_size=10),
                  margin=dict(l=8,r=12,t=28,b=28))
    with st.container(key='basket_detail_row'):
        left,right=st.columns(2,gap='small')
    with left,st.container(border=True,key='basket_items_panel'):
        subtitle='Selected premise vs cheapest premise · Same basket quantities' if comparing else best.premise
        overview_panel('Item cost comparison' if comparing else 'Item costs',subtitle)
        basket_item_costs(lines,selectable,best_code,focus_code,codes)
    focus_district=district if districts else selected.district if ref!='cheapest' else None
    with right,st.container(border=True,key='comparison_areas_panel'):
        statewide=complete
        if districts:
            statewide,_=forecast_baskets(forecasts,prem,quantities,target,chosen_states,[])
            statewide=statewide[statewide.complete]
        basket_district_ranges(statewide,state,focus_district)
    targets={}
    if ref!='cheapest':
        targets['.st-key-comparison_ranking_panel .prediction-rank-list']=str(focus_code)
    if focus_district:
        targets['.basket-district-list']=focus_district
    scroll_to_rankings(targets)


def sidebar_data(latest,batch,today):
    entries=(('Latest data',latest),('Forecast batch',batch),('Today (MYT)',today))
    rows=''.join(f'<dt>{label}</dt><dd>{datefmt(day)}</dd>' for label,day in entries)
    return f'<dl class="sidebar-data">{rows}</dl>'


